def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def as_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def pos(name, default=(0, 0)):
        p = observation.get(name, default)
        q = as_pair(p)
        return q if q is not None else default

    def first_pair(seq):
        if not seq:
            return None
        for item in seq:
            q = as_pair(item)
            if q is not None:
                return q
        return None

    sx, sy = pos("self_position")
    ox, oy = pos("opponent_position", (sx, sy))
    env = observation.get("environment_name", "resource_collection")
    role = observation.get("self_role", "")

    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    if not isinstance(w, int):
        w = 0
    if not isinstance(h, int):
        h = 0

    def step_toward(tx, ty):
        return [sgn(tx - sx), sgn(ty - sy)]

    def step_away(tx, ty):
        return [sgn(sx - tx), sgn(sy - ty)]

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_toward(ox, oy)
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        if corners:
            target = max(corners, key=lambda p: abs(p[0] - ox) + abs(p[1] - oy))
            return step_toward(target[0], target[1])
        return step_away(ox, oy)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("neutral_cells")
        best = first_pair(targets)
        if best is not None:
            return step_toward(best[0], best[1])
        return step_toward(ox, oy)

    resources = observation.get("resources")
    if not resources:
        resources = observation.get("resource_positions")
    best = first_pair(resources)
    if best is not None:
        # Slight bias toward contesting opponent only when adjacent to resource-less state.
        return step_toward(best[0], best[1])

    # Default: approach opponent, simple and stable.
    return step_toward(ox, oy)

